// The window ends at settlement and starts N minutes earlier. Near-settlement
// is where slippage is worst, because depth thins as the outcome becomes clear.
const form = $('Market and order size').first().json;
const market = $input.first().json;

const end = new Date(market.end_date);
const minutes = Number(form['Minutes before close']) || 5;
const start = new Date(end.getTime() - minutes * 60_000);

const iso = (d) => d.toISOString().replace(/\.\d{3}Z$/, 'Z');

return [{
  json: {
    slug: market.slug,
    question: market.question,
    shares: Number(form['Shares to buy']) || 100,
    start_ts: iso(start),
    end_ts: iso(end),
  },
}];

// Fill the order against real resting size, level by level, and compare the
// average fill price to the midpoint. The gap is the slippage a price series
// cannot show you: the midpoint is where the market was, not where you could
// have traded.
const ctx = $('Build the time window').first().json;
const books = $input.first().json;
const want = ctx.shares;
const out = [];

for (const [outcome, snapshots] of Object.entries(books.data ?? {})) {
  for (const snap of snapshots) {
    const asks = snap.asks ?? [];
    const bids = snap.bids ?? [];

    // Binary markets go one-sided as they resolve. Nothing to fill against.
    if (asks.length === 0) {
      out.push({ json: { outcome, t: snap.t, fillable: false, reason: 'no asks resting' } });
      continue;
    }

    const bestAsk = asks[0][0];
    const bestBid = bids.length ? bids[0][0] : null;
    const mid = bestBid === null ? bestAsk : (bestBid + bestAsk) / 2;

    let remaining = want;
    let cost = 0;
    let filled = 0;
    let levels = 0;

    for (const [price, size] of asks) {
      if (remaining <= 0) break;
      const take = Math.min(remaining, size);
      cost += take * price;
      filled += take;
      remaining -= take;
      levels += 1;
    }

    const avg = filled > 0 ? cost / filled : null;

    out.push({
      json: {
        outcome,
        t: snap.t,
        fillable: remaining <= 0,
        shares_requested: want,
        shares_filled: Number(filled.toFixed(2)),
        levels_consumed: levels,
        best_bid: bestBid,
        best_ask: bestAsk,
        midpoint: mid === null ? null : Number(mid.toFixed(4)),
        avg_fill_price: avg === null ? null : Number(avg.toFixed(4)),
        total_cost: Number(cost.toFixed(2)),
        slippage_vs_mid_pct:
          avg !== null && mid ? Number((((avg - mid) / mid) * 100).toFixed(2)) : null,
      },
    });
  }
}

return out;

// One row per outcome so the result is readable rather than 600 snapshots.
const rows = $input.all().map((i) => i.json);
const byOutcome = {};

for (const r of rows) {
  (byOutcome[r.outcome] ??= []).push(r);
}

return Object.entries(byOutcome).map(([outcome, rs]) => {
  const priced = rs.filter((r) => r.slippage_vs_mid_pct !== null);
  const unfillable = rs.filter((r) => !r.fillable).length;
  const slips = priced.map((r) => r.slippage_vs_mid_pct).sort((a, b) => a - b);
  const worst = priced.reduce((a, b) => (a && a.slippage_vs_mid_pct > b.slippage_vs_mid_pct ? a : b), null);

  return {
    json: {
      outcome,
      snapshots: rs.length,
      could_not_fill: unfillable,
      could_not_fill_pct: Number(((unfillable / rs.length) * 100).toFixed(1)),
      median_slippage_pct: slips.length ? slips[Math.floor(slips.length / 2)] : null,
      worst_slippage_pct: worst ? worst.slippage_vs_mid_pct : null,
      worst_at: worst ? worst.t : null,
    },
  };
});
